select #{uid} uid, p.id , pac.createtime as createtime, u.login_name employee_id, p.text_paper, p.word_paper, p.search_web, pt.dept_name research_room, p.user_id, d.dept_name dname, pt.dept_name college, p.teacher_name teacher_name, u.tea_zhicheng on_campus_title, p.paper_title , p.paper_type, p.paper_category, p.published_journal, p.publication_time, p.is_industry_collaborative, p.is_local_collaborative, p.is_international_collaborative, p.is_cross_discipline, p.paper_ranking, p.research_score, p.remarks, p.state, pa1.user_name as first_author_name, pa1.user_id as first_author_id, pa1.score as first_author_score, pa2.user_name as second_author_name, pa2.user_id as second_author_id, pa2.score as second_author_score, pa3.user_name as third_author_name, pa3.user_id as third_author_id, pa3.score as third_author_score, pa4.user_name as fourth_author_name, pa4.user_id as fourth_author_id, pa4.score as fourth_author_score, pac.user_name as corresponding_author_name, pac.user_id as corresponding_author_id, pac.score as corresponding_author_score from sci_paper_a p left join sys_user u on p.user_id = u.user_id left join sys_dept d on u.dept_id = d.dept_id left join sys_dept pt on d.parent_id = pt.dept_id left join ( select pa.paper_id, su.user_name ,su.user_id ,pa.score from paper_author pa left join sys_user su on pa.user_id = su.user_id where pa.author_order = '1' ) pa1 on p.id = pa1.paper_id left join ( select pa.paper_id, su.user_name ,su.user_id ,pa.score from paper_author pa left join sys_user su on pa.user_id = su.user_id where pa.author_order = '2' ) pa2 on p.id = pa2.paper_id left join ( select pa.paper_id, su.user_name ,su.user_id,pa.score from paper_author pa left join sys_user su on pa.user_id = su.user_id where pa.author_order = '3' ) pa3 on p.id = pa3.paper_id left join ( select pa.paper_id, su.user_name ,su.user_id,pa.score from paper_author pa left join sys_user su on pa.user_id = su.user_id where pa.author_order = '4' ) pa4 on p.id = pa4.paper_id left join ( select pa.paper_id, su.user_name ,su.user_id,pa.score ,pa.create_time as createtime from paper_author pa left join sys_user su on pa.user_id = su.user_id where pa.author_level = '0' ) pac on p.id = pac.paper_id where 1=1
and p.user_id = #{userId}
and pac.createtime >= #{startTime}
and pac.createtime <= #{endTime}
AND d.parent_id = #{Pcollege}
AND pt.dept_id = #{college}
AND d.dept_id = #{major}
and u.tea_zhicheng =#{jobTitle}
and p.paper_title like concat('%', #{topicName}, '%')
AND p.state in (3,5,7,9,10,22,44,99)
AND p.state in (1,2,4,6,11,33)
AND p.state in (8)
order by createtime desc

select sp.dept_name college, sd.dept_name dname, su.login_name loginName, su.user_name userName, spa.published_journal , spa.paper_title , pa.score as change_value, spa.state from paper_author pa left join sci_paper_a spa on pa.paper_id = spa.id left join sys_user su on pa.user_id = su.user_id left join sys_dept sd on su.dept_id = sd.dept_id left join sys_dept sp on sd.parent_id = sp.dept_id where 1 = 1
AND sp.dept_id = #{college}
AND sd.dept_id = #{major}
AND su.user_id = #{teacherName}
and spa.createtime >= #{startTime}
and spa.createtime <= #{endTime}
and spa.paper_title like concat('%', #{topicName}, '%')
AND spa.state in (3,5,7,9,10,22,44,99)
AND spa.state in (1,2,4,6,11,33)
AND spa.state in (8)
and pa.user_id != '-1' and spa.paper_title is not null and pa.score !='0' order by college asc,dname asc,su.login_name asc
